div.script:
                        
                        // Odoo API Helper
                        const odooRpc = {
                            call: function(model, method, args, kwargs) {
                                return new Promise((resolve, reject) => {
                                    fetch('/web/dataset/call_kw/' + model + '/' + method, {
                                        method: 'POST',
                                        headers: {
                                            'Content-Type': 'application/json',
                                            'X-CSRF-Token': document.querySelector('[name=csrf_token]')?.value || ''
                                        },
                                        body: JSON.stringify({
                                            jsonrpc: '2.0',
                                            method: 'call',
                                            params: {
                                                model: model,
                                                method: method,
                                                args: args || [],
                                                kwargs: kwargs || {}
                                            },
                                            id: Math.random()
                                        })
                                    })
                                    .then(response => response.json())
                                    .then(data => {
                                        if (data.result) resolve(data.result);
                                        else reject(data.error);
                                    })
                                    .catch(reject);
                                });
                            }
                        };

                        // Fetch receipt from Odoo via dedicated API
                        function fetchReceipt(receiptId) {
                            document.getElementById('loading').style.display = 'block';
                            document.getElementById('content').style.display = 'none';

                            fetch('/sand/api/receipt/' + encodeURIComponent(receiptId), {
                                method: 'POST',
                                headers: {
                                    'Content-Type': 'application/json',
                                }
                            })
                            .then(response => {
                                if (!response.ok) throw new Error('Network response was not ok');
                                return response.json();
                            })
                            .then(result => {
                                if (result && result.status === 'success') {
                                    displayReceipt(result.data);
                                    showSuccess('Receipt loaded successfully!');
                                } else {
                                    showError(result?.message || 'Receipt not found. Please check the ID.');
                                }
                                document.getElementById('loading').style.display = 'none';
                                document.getElementById('content').style.display = 'block';
                            })
                            .catch(error => {
                                console.error('Error:', error);
                                showError('Could not connect to server. Please try again later.');
                                document.getElementById('loading').style.display = 'none';
                                document.getElementById('content').style.display = 'block';
                            });
                        }

                        // Display receipt data
                        function displayReceipt(data) {
                            setText('orderId', data.order_id);
                            setText('customerName', data.customer_name);
                            setText('customerMobile', data.customer_mobile);
                            setText('registrationDate', data.registration_date);
                            setText('registrationType', data.registration_type === 'general' ? 'GENERAL SAND CONSUMPTION' : data.registration_type);
                            setText('registrationQty', data.registration_qty ? parseFloat(data.registration_qty).toFixed(1) + ' MT' : '-');
                            setText('regAddress', data.registration_address);
                            
                            setText('availableQty', data.available_sand_qty ? parseFloat(data.available_sand_qty).toFixed(1) + ' MT' : '-');
                            setText('eligibleQty', data.eligible_sand_qty ? parseFloat(data.eligible_sand_qty).toFixed(1) + ' MT' : '-');

                            setText('dispatchId', data.dispatch_id);
                            setText('tripNo', data.trip_no);
                            setText('vehicleNo', data.vehicle_no);
                            setText('driverInfo', (data.driver_name || '-') + ' / ' + (data.driver_phone || '-'));
                            setText('dispatchQty', data.sand_quantity ? parseFloat(data.sand_quantity).toFixed(1) + ' MT' : '-');
                            setText('dispatchDate', data.dispatch_date);
                            setText('address', data.address);

                            const statusEl = document.getElementById('status');
                            if (statusEl) {
                                statusEl.innerText = (data.state || 'draft').toUpperCase();
                                statusEl.style.backgroundColor = data.state === 'confirmed' || data.state === 'printed' ? '#d4edda' : '#feebc8';
                                statusEl.style.color = data.state === 'confirmed' || data.state === 'printed' ? '#155724' : '#744210';
                            }
                        }

                        // Helper functions
                        function setText(id, text) {
                            const el = document.getElementById(id);
                            if (el) el.innerText = text || '-';
                        }

                        function formatDate(dateStr) {
                            return dateStr || '-';
                        }

                        function searchReceipt() {
                            const receiptId = document.getElementById('receiptInput').value.trim();
                            if (!receiptId) {
                                showError('Please enter a Receipt ID');
                                return;
                            }
                            fetchReceipt(receiptId);
                        }

                        function clearInput() {
                            document.getElementById('receiptInput').value = '';
                            clearMessages();
                        }

                        function showSuccess(msg) {
                            const el = document.getElementById('successMsg');
                            el.innerText = '✓ ' + msg;
                            el.style.display = 'block';
                            document.getElementById('errorMsg').style.display = 'none';
                            setTimeout(() => el.style.display = 'none', 3000);
                        }

                        function showError(msg) {
                            const el = document.getElementById('errorMsg');
                            el.innerText = '✗ ' + msg;
                            el.style.display = 'block';
                            document.getElementById('successMsg').style.display = 'none';
                        }

                        function clearMessages() {
                            document.getElementById('successMsg').style.display = 'none';
                            document.getElementById('errorMsg').style.display = 'none';
                        }

                        // Allow Enter key to search
                        document.getElementById('receiptInput')?.addEventListener('keypress', function(e) {
                            if (e.key === 'Enter') searchReceipt();
                        });

                        // Initialize - load from URL if available
                        window.addEventListener('DOMContentLoaded', () => {
                            const params = new URLSearchParams(window.location.search);
                            const receiptId = params.get('receipt_id');
                            if (receiptId) {
                                document.getElementById('receiptInput').value = receiptId;
                                searchReceipt();
                            } else {
                                document.getElementById('loading').style.display = 'none';
                                document.getElementById('content').style.display = 'block';
                            }
                        });
